<?php session_start();if(!isset($_SESSION["admin_id"])){header("Location: ../login.php");exit;}require_once "../../config/database.php";require_once "../geo_helper.php";$row=[];$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$geometry=$row["geometry"]??"";if(isset($_FILES["geojson"])&&($_FILES["geojson"]["error"]??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){[$geom,$geoError]=read_geojson_upload($_FILES["geojson"]);if($geoError)$error=$geoError;else$geometry=json_encode($geom,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}if(!$error){$sql="INSERT INTO irigasi (nama_irigasi,panjang,kondisi,sumber_air,keterangan,geometry) VALUES (?,?,?,?,?,?)";$pdo->prepare($sql)->execute([trim($_POST["nama_irigasi"]??""),($_POST["panjang"]!==""?$_POST["panjang"]:0),trim($_POST["kondisi"]??""),trim($_POST["sumber_air"]??""),trim($_POST["keterangan"]??""),$geometry]); header("Location: index.php");exit;}}$admin_root='..';$active='irigasi';?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tambah Jaringan Irigasi | Padi Seriti</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap"><link rel="stylesheet" href="../admin.css"></head><body class="admin-page"><div class="admin-shell"><?php include "../sidebar.php"; ?><main class="admin-main"><div class="topbar"><div><div class="eyebrow">DATA SPASIAL / Jaringan Irigasi</div><h1>Tambah Jaringan Irigasi</h1></div><a href="index.php" class="btn-back"><i class="fa-solid fa-arrow-left"></i> Kembali</a></div><?php if($error):?><div class="alert alert-danger mb-3"><?=e($error)?></div><?php endif;?><div class="form-wrap"><form method="post" enctype="multipart/form-data" class="form-card"><section class="form-section"><div class="section-head"><div class="section-icon"><i class="fa-solid fa-water"></i></div><div><h3>Informasi Jaringan Irigasi</h3><p>Lengkapi data atribut.</p></div></div><div class="form-grid"><div class="field"><label>Nama Irigasi</label><input type="text" name="nama_irigasi" value="<?=e($row["nama_irigasi"]??"")?>" ></div><div class="field"><label>Panjang (m)</label><input type="number" name="panjang" value="<?=e($row["panjang"]??"")?>" step="0.01" min="0"></div><div class="field"><label>Kondisi</label><select name="kondisi"><option value="">-- Pilih Kondisi --</option><option>Baik</option><option>Sedang</option><option>Rusak</option><option>Tidak Ada</option></select></div><div class="field"><label>Sumber Air</label><input type="text" name="sumber_air" value="<?=e($row["sumber_air"]??"")?>" ></div><div class="field"><label>Keterangan</label><input type="text" name="keterangan" value="<?=e($row["keterangan"]??"")?>" ></div></div></section><section class="form-section"><div class="section-head"><div class="section-icon"><i class="fa-solid fa-location-dot"></i></div><div><h3>Data Spasial</h3><p>Upload geometry GeoJSON.</p></div></div><div class="upload-box"><div class="field"><label>File GeoJSON <span>*</span></label><input type="file" name="geojson" id="geojson" accept=".geojson,.json,application/geo+json,application/json" required><small>Format .geojson/.json, maksimal 10 MB, dan untuk tambah/edit harus berisi tepat 1 feature.</small><div id="fileName" class="file-name"></div><?php if(!empty($row['geometry'])):?><div class="geo-status geo-ok"><i class="fa-solid fa-circle-check"></i> Geometry tersimpan. Upload file baru jika ingin menggantinya.</div><?php endif;?></div></div></section><div class="form-actions"><a href="index.php" class="btn-cancel">Batal</a><button class="btn-save" type="submit"><i class="fa-solid fa-floppy-disk"></i> Simpan Data</button></div></form></div></main></div><script>const f=document.getElementById('geojson'),n=document.getElementById('fileName');f&&f.addEventListener('change',()=>n.textContent=f.files.length?'File dipilih: '+f.files[0].name:'');</script></body></html>